//! Bind generated bytes to fixed composition slots without granting execution.
use super::pins::{digest, index, logical};
use super::{BoundCompositionInputs, Result, check_composition_snapshot_binding, invalid, text};
use crate::{
    Document, DocumentKind, FormatError, SchemaRegistry,
    artifacts::{ProvidedFile, validate_port_pair, verify_reference},
    execution::{ExecutionRecipe, generation_task_digest, source_manifest, validate_sources},
    policy_digest, shape_digest, source_digest, structure_digest,
};
use madb_app::{
    QueryError,
    inputs::{FrozenInputs, capture_inputs, check_input_inventory},
    ports::{FileReference, ReadWorkspace},
};
use madb_model::{Digest, Id, LogicalPath};
use madb_protocol::Value;
use std::collections::{BTreeMap, BTreeSet};

pub struct GenerationSchemaPaths {
    pub generate_request: LogicalPath,
    pub output_set: LogicalPath,
}
/// These requirements and recipes come from the host's fixed composition
/// recipe, never from a helper's output or an `accepted` flag.
pub struct GenerationStepRequirement<'a> {
    pub recipe: &'a ExecutionRecipe,
    pub producer: Id,
    pub output_slots: Vec<Id>,
    pub output_root: LogicalPath,
}
pub struct GenerationBindingContext<'a> {
    pub lock: ProvidedFile<'a>,
    pub profile: ProvidedFile<'a>,
    pub contract: ProvidedFile<'a>,
    pub schema_paths: &'a GenerationSchemaPaths,
    pub required_steps: &'a [GenerationStepRequirement<'a>],
}
/// Untrusted result data. A frozen inventory proves captured bytes, not that a
/// particular process produced them or completed its cleanup.
pub struct GenerationStepObservation<'a> {
    pub step_id: Id,
    pub request: ProvidedFile<'a>,
    pub installed_tool: ProvidedFile<'a>,
    pub outputs: &'a FrozenInputs,
}
pub struct BoundGeneratedOutputs {
    slots: Vec<BoundGeneratedSlot>,
    steps: Vec<(Id, FrozenInputs)>,
}
impl BoundGeneratedOutputs {
    pub fn slots(&self) -> &[BoundGeneratedSlot] {
        &self.slots
    }
    /// Original per-step manifests and their complete frozen inventories. They
    /// remain separate domains; this does not synthesize a combined OutputSet.
    pub fn output_sets(&self) -> impl Iterator<Item = (&Id, &FrozenInputs)> {
        self.steps.iter().map(|(id, files)| (id, files))
    }
}
/// A slot's immutable bytes and lineage. It is neither an ArtifactRecipe nor a
/// Source batch, execution receipt, certification or publication authority.
pub struct BoundGeneratedSlot {
    producer: Id,
    slot: Id,
    files: FrozenInputs,
    task_digest: Digest,
    generation_id: Digest,
    profile_digest: Digest,
    input_digest: Digest,
}
impl BoundGeneratedSlot {
    pub fn producer(&self) -> &Id {
        &self.producer
    }
    pub fn slot(&self) -> &Id {
        &self.slot
    }
    pub fn files(&self) -> &FrozenInputs {
        &self.files
    }
    pub fn task_digest(&self) -> &Digest {
        &self.task_digest
    }
    pub fn generation_id(&self) -> &Digest {
        &self.generation_id
    }
    pub fn profile_digest(&self) -> &Digest {
        &self.profile_digest
    }
    pub fn input_digest(&self) -> &Digest {
        &self.input_digest
    }
}

pub fn bind_generated_outputs(
    inputs: &BoundCompositionInputs,
    context: GenerationBindingContext<'_>,
    observations: &[GenerationStepObservation<'_>],
) -> Result<BoundGeneratedOutputs> {
    let registry = SchemaRegistry::new()?;
    check_schemas(inputs, context.schema_paths)?;
    let lock = registry.decode(DocumentKind::Lock, context.lock.bytes)?;
    if lock.value() != inputs.locked_document.value() {
        return Err(invalid(
            "LOCK003",
            "lock",
            "generation uses a different bound lock",
        ));
    }
    check_file(&inputs.profile_reference, &context.profile)?;
    let snapshot = registry.decode(DocumentKind::ContractIr, context.contract.bytes)?;
    check_composition_snapshot_binding(inputs, &snapshot)?;
    check_ir_identities(&snapshot)?;
    let symbols = index(&snapshot.value()["symbols"], "public_id")?
        .keys()
        .map(|id| (*id).to_owned())
        .collect::<BTreeSet<_>>();
    let expected_inputs = generation_inputs(inputs, &context)?;
    let slots = declared_slots(inputs)?;
    let requirements = bind_requirements(&slots, context.required_steps)?;
    let mut observed = BTreeMap::new();
    for observation in observations {
        if observed
            .insert(observation.step_id.as_str(), observation)
            .is_some()
        {
            return Err(invalid(
                "InputInvalid",
                "steps",
                "duplicate generation observation",
            ));
        }
    }
    if requirements.keys().ne(observed.keys()) {
        return Err(invalid(
            "InputInvalid",
            "steps",
            "missing or extra generation step",
        ));
    }
    let components = index(&inputs.composition().value()["components"], "id")?;
    let binding = RequestBinding {
        inputs,
        context: &context,
        snapshot: &snapshot,
        expected_inputs: &expected_inputs,
        components: &components,
    };
    let mut bound = Vec::new();
    for (id, required) in requirements {
        let observation = observed[id];
        let request = registry.decode(DocumentKind::GenerateRequest, observation.request.bytes)?;
        check_request(&binding, required, observation, &request)?;
        let manifest_bytes = source_manifest(observation.outputs).map_err(query_error)?;
        let output = registry.decode(DocumentKind::OutputSet, manifest_bytes)?;
        if output.value()["manifest_path"] != required.recipe.response_path.as_str() {
            return Err(invalid(
                "FILE003",
                "manifest_path",
                "output manifest differs from fixed recipe",
            ));
        }
        validate_port_pair(&request, &output)?;
        validate_sources(&output, &symbols).map_err(query_error)?;
        let output_files = index(&output.value()["files"], "path")?;
        let expected_paths = required
            .output_slots
            .iter()
            .flat_map(|slot| {
                slots[&(required.producer.as_str(), slot.as_str())]
                    .iter()
                    .map(LogicalPath::as_str)
            })
            .collect::<BTreeSet<_>>();
        if expected_paths
            .iter()
            .copied()
            .ne(output_files.keys().copied())
        {
            return Err(invalid(
                "InputInvalid",
                "files",
                "generated files differ from exact fixed slot closure",
            ));
        }
        // Domains are already frozen. Check names against all protected inputs,
        // including the actual request, lock, profile, IR and manifest name.
        let mut paths = expected_inputs.keys().cloned().collect::<Vec<_>>();
        paths.push(required.recipe.request.path.clone());
        paths.extend(
            observation
                .outputs
                .references()
                .map(|file| file.path.clone()),
        );
        super::ownership::check_output_paths(&paths)?;
        for slot in &required.output_slots {
            let names = &slots[&(required.producer.as_str(), slot.as_str())];
            let refs = observation
                .outputs
                .references()
                .filter(|file| names.contains(&file.path))
                .cloned()
                .collect::<Vec<_>>();
            let files = capture_inputs(&SnapshotWorkspace(observation.outputs), refs)
                .map_err(query_error)?;
            bound.push(BoundGeneratedSlot {
                producer: required.producer.clone(),
                slot: slot.clone(),
                files,
                task_digest: digest(&output.value()["task_digest"])?,
                generation_id: digest(&output.value()["generation_id"])?,
                profile_digest: digest(&output.value()["profile_digest"])?,
                input_digest: digest(&output.value()["input_digest"])?,
            });
        }
    }
    bound.sort_by(|a, b| (&a.producer, &a.slot).cmp(&(&b.producer, &b.slot)));
    let steps = observed
        .into_values()
        .map(|observation| (observation.step_id.clone(), observation.outputs.clone()))
        .collect();
    Ok(BoundGeneratedOutputs {
        slots: bound,
        steps,
    })
}

fn check_schemas(inputs: &BoundCompositionInputs, paths: &GenerationSchemaPaths) -> Result<()> {
    let expected = [
        (
            &paths.generate_request,
            include_bytes!(concat!(
                env!("CARGO_MANIFEST_DIR"),
                "/../../docs/schemas/generate-request.schema.json"
            ))
            .as_slice(),
        ),
        (
            &paths.output_set,
            include_bytes!(concat!(
                env!("CARGO_MANIFEST_DIR"),
                "/../../docs/schemas/output-set.schema.json"
            ))
            .as_slice(),
        ),
    ];
    if paths.generate_request == paths.output_set {
        return Err(invalid(
            "LOCK006",
            "schemas",
            "distinct decoder schemas need distinct paths",
        ));
    }
    let schemas = index(&inputs.locked_document.value()["schemas"], "path")?;
    for (path, bytes) in expected {
        let reference = schemas.get(path.as_str()).ok_or_else(|| {
            invalid(
                "LOCK005",
                path.as_str(),
                "generation decoder schema is not locked",
            )
        })?;
        let (_, actual) = inputs
            .frozen_inputs
            .files()
            .find(|(file, _)| &file.path == path)
            .ok_or_else(|| {
                invalid(
                    "FILE003",
                    path.as_str(),
                    "generation decoder schema is not frozen",
                )
            })?;
        verify_reference(
            reference,
            &ProvidedFile {
                path: path.as_str(),
                bytes: actual,
            },
        )?;
        if actual != bytes {
            return Err(invalid(
                "FILE004",
                path.as_str(),
                "generation decoder differs from actual bundled schema",
            ));
        }
    }
    Ok(())
}
fn check_ir_identities(ir: &Document) -> Result<()> {
    if ir.value()["structure_digest"] != structure_digest(ir)? {
        return Err(invalid(
            "HASH001",
            "structure_digest",
            "IR structure identity differs",
        ));
    }
    if ir.value()["policy_digest"] != policy_digest(ir)? {
        return Err(invalid(
            "HASH002",
            "policy_digest",
            "IR policy identity differs",
        ));
    }
    for (id, symbol) in index(&ir.value()["symbols"], "public_id")? {
        if symbol["shape_digest"] != shape_digest(ir, id)? {
            return Err(invalid("HASH003", id, "IR shape identity differs"));
        }
    }
    Ok(())
}
type Slots<'a> = BTreeMap<(&'a str, &'a str), Vec<LogicalPath>>;
fn declared_slots(inputs: &BoundCompositionInputs) -> Result<Slots<'_>> {
    let mut slots = BTreeMap::new();
    for asset in inputs.composition().value()["assets"]
        .as_array()
        .expect("bound assets")
    {
        let source = &asset["source"];
        if source["kind"] == "generated" {
            let key = (text(&source["producer"])?, text(&source["output_slot"])?);
            let mut paths = source["paths"]
                .as_array()
                .expect("bound paths")
                .iter()
                .map(logical)
                .collect::<Result<Vec<_>>>()?;
            paths.sort();
            if slots.insert(key, paths).is_some() {
                return Err(invalid("InputInvalid", "slots", "duplicate bound slot"));
            }
        }
    }
    Ok(slots)
}
fn bind_requirements<'a>(
    slots: &Slots<'_>,
    requirements: &'a [GenerationStepRequirement<'a>],
) -> Result<BTreeMap<&'a str, &'a GenerationStepRequirement<'a>>> {
    let mut steps = BTreeMap::new();
    let mut seen = BTreeSet::new();
    for requirement in requirements {
        if requirement.output_slots.is_empty()
            || steps
                .insert(requirement.recipe.id.as_str(), requirement)
                .is_some()
        {
            return Err(invalid(
                "InputInvalid",
                "steps",
                "empty or duplicate fixed generation step",
            ));
        }
        for slot in &requirement.output_slots {
            let key = (requirement.producer.as_str(), slot.as_str());
            if !slots.contains_key(&key) || !seen.insert(key) {
                return Err(invalid(
                    "InputInvalid",
                    "slots",
                    "unknown or multiply assigned generated slot",
                ));
            }
        }
    }
    if seen.iter().copied().ne(slots.keys().copied()) {
        return Err(invalid(
            "InputInvalid",
            "slots",
            "fixed steps do not cover every generated slot",
        ));
    }
    Ok(steps)
}
fn generation_inputs(
    inputs: &BoundCompositionInputs,
    context: &GenerationBindingContext<'_>,
) -> Result<BTreeMap<LogicalPath, FileReference>> {
    let mut refs = inputs
        .frozen_inputs
        .references()
        .map(|r| (r.path.clone(), r.clone()))
        .collect::<BTreeMap<_, _>>();
    for file in [&context.lock, &context.profile, &context.contract] {
        let reference = FileReference {
            path: LogicalPath::new(file.path)
                .map_err(|e| invalid("FILE001", file.path, e.to_string()))?,
            digest: Digest::of_bytes(file.bytes),
            size: file.bytes.len() as u64,
        };
        if let Some(prior) = refs.insert(reference.path.clone(), reference.clone()) {
            if prior != reference {
                return Err(invalid(
                    "FILE004",
                    file.path,
                    "context conflicts with frozen input",
                ));
            }
            let (_, prior_bytes) = inputs
                .frozen_inputs
                .files()
                .find(|(r, _)| r.path == reference.path)
                .ok_or_else(|| {
                    invalid("FILE004", file.path, "context references alias one another")
                })?;
            if prior_bytes != file.bytes {
                return Err(invalid(
                    "FILE004",
                    file.path,
                    "context bytes differ from frozen input",
                ));
            }
        }
    }
    check_input_inventory(&refs.values().cloned().collect::<Vec<_>>()).map_err(query_error)?;
    Ok(refs)
}
struct RequestBinding<'a> {
    inputs: &'a BoundCompositionInputs,
    context: &'a GenerationBindingContext<'a>,
    snapshot: &'a Document,
    expected_inputs: &'a BTreeMap<LogicalPath, FileReference>,
    components: &'a BTreeMap<&'a str, &'a Value>,
}
fn check_request(
    binding: &RequestBinding<'_>,
    required: &GenerationStepRequirement<'_>,
    observed: &GenerationStepObservation<'_>,
    request: &Document,
) -> Result<()> {
    let inputs = binding.inputs;
    let context = binding.context;
    let snapshot = binding.snapshot;
    let expected_inputs = binding.expected_inputs;
    let components = binding.components;
    let recipe = required.recipe;
    let q = request.value();
    let p = inputs.profile().value();
    check_file(&recipe.request, &observed.request)?;
    if q["boundary_id"] != snapshot.value()["boundary_id"]
        || q["selector"] != snapshot.value()["selector"]
        || q["output_root"] != required.output_root.as_str()
    {
        return Err(invalid(
            "LOCK001",
            "request",
            "generation selector, boundary or output domain differs",
        ));
    }
    for (key, kind, file) in [
        ("lock", DocumentKind::Lock, &context.lock),
        ("profile", DocumentKind::ProfileV2, &context.profile),
        ("contract", DocumentKind::ContractIr, &context.contract),
    ] {
        if q[key]["schema"] != kind.schema_id() {
            return Err(invalid(
                "FMT003",
                key,
                "generation reference has wrong schema",
            ));
        }
        verify_reference(&q[key], file)?;
    }
    if components.get(required.producer.as_str()).copied() != Some(&q["component"]) {
        return Err(invalid(
            "LOCK004",
            "component",
            "generation producer tuple differs from fixed slot owner",
        ));
    }
    if q["input_digest"] != inputs.source_digest()
        || source_digest(&q["inputs"])? != inputs.source_digest()
        || q["contract_digest"] != snapshot.value()["structure_digest"]
        || q["policy_digest"] != snapshot.value()["policy_digest"]
    {
        return Err(invalid(
            "LOCK005",
            "request",
            "generation source or contract lineage differs",
        ));
    }
    let mut recipe_inputs = BTreeMap::new();
    for file in &recipe.inputs {
        if recipe_inputs
            .insert(file.path.clone(), file.clone())
            .is_some()
        {
            return Err(invalid("LOCK006", "inputs", "duplicate recipe input"));
        }
    }
    if &recipe_inputs != expected_inputs
        || recipe_inputs.contains_key(&recipe.request.path)
        || recipe.input_schemas.len() != recipe_inputs.len()
        || recipe.input_schemas.keys().ne(recipe_inputs.keys())
    {
        return Err(invalid(
            "LOCK005",
            "inputs",
            "recipe does not materialize the exact fixed input closure",
        ));
    }
    for (key, kind) in [
        ("lock", DocumentKind::Lock),
        ("profile", DocumentKind::ProfileV2),
        ("contract", DocumentKind::ContractIr),
    ] {
        if recipe.input_schemas[&logical(&q[key]["path"])?].as_str() != kind.schema_id() {
            return Err(invalid(
                "FMT003",
                key,
                "recipe input schema differs from request",
            ));
        }
    }
    for file in q["inputs"].as_array().expect("checked inputs") {
        let name = logical(&file["path"])?;
        if recipe.input_schemas.get(&name).map(Id::as_str) != file["schema"].as_str() {
            return Err(invalid(
                "FMT003",
                name.as_str(),
                "source schema differs between request and recipe",
            ));
        }
    }
    let tools = index(&p["tools"], "id")?;
    let tool = tools
        .get(recipe.tool.id.as_str())
        .ok_or_else(|| invalid("LOCK004", "tool", "fixed tool is absent from bound profile"))?;
    if tool["version"] != recipe.tool.version
        || tool["sha256"] != recipe.tool.digest.as_str()
        || recipe.installed_tool.digest != recipe.tool.digest
    {
        return Err(invalid(
            "LOCK004",
            "tool",
            "fixed execution image differs from locked tool identity",
        ));
    }
    check_file(&recipe.installed_tool, &observed.installed_tool)?;
    if q["task_digest"]
        != generation_task_digest(request, &recipe.projection().map_err(query_error)?)?
    {
        return Err(invalid(
            "PLAN002",
            "task_digest",
            "generation task differs from fixed execution recipe",
        ));
    }
    Ok(())
}
fn check_file(reference: &FileReference, file: &ProvidedFile<'_>) -> Result<()> {
    if reference.path.as_str() != file.path {
        return Err(invalid("FILE003", file.path, "wrong logical file"));
    }
    if reference.size != file.bytes.len() as u64 || reference.digest != Digest::of_bytes(file.bytes)
    {
        return Err(invalid(
            "FILE004",
            file.path,
            "actual byte identity differs",
        ));
    }
    Ok(())
}
fn query_error(e: QueryError) -> FormatError {
    if let Some(first) = e.findings.first() {
        invalid(first.code, &first.subject, e.to_string())
    } else {
        invalid("InputInvalid", "generation", e.to_string())
    }
}
struct SnapshotWorkspace<'a>(&'a FrozenInputs);
impl ReadWorkspace for SnapshotWorkspace<'_> {
    fn read(&self, path: &LogicalPath, _limit: usize) -> madb_app::Result<Option<Vec<u8>>> {
        Ok(self
            .0
            .files()
            .find(|(r, _)| &r.path == path)
            .map(|(_, b)| b.to_vec()))
    }
}
